/// <summary>
/// UI helpers shared by the action menu items of the insurance card reconciliation.
/// </summary>
public final class PMINSRECFormHelper
{
}

Method.Source:
    /// <summary>
    /// Re-reads the main data source of the calling form after an action has changed data.
    /// </summary>
    public static void refreshCaller(Args _args)
    {
        FormRun        formRun;
        FormDataSource formDataSource;

        if (_args && _args.caller() is FormRun)
        {
            formRun        = _args.caller();
            formDataSource = formRun.dataSource(1);

            if (formDataSource)
            {
                formDataSource.research(true);
            }
        }
    }

    /// <summary>
    /// Asks the user for a file. Returns null when the upload is cancelled or fails.
    /// </summary>
    public static FileUploadTemporaryStorageResult uploadFile()
    {
        FileUploadTemporaryStorageResult result = File::GetFileFromUser() as FileUploadTemporaryStorageResult;

        if (!result || !result.getUploadStatus())
        {
            return null;
        }

        return result;
    }
